  :root{
    --bg:#FAF8F6; --surface:#fff; --soft:#F5F2EF; --blush:#FFF0EB; --cream:#FFF8F2;
    --ink:#272321; --muted:#817B76; --border:#EAE6E1;
    --primary:#FF704D; --primary-press:#F45E3D; --primary-soft:#FFE9E2; --primary-tint:#FFF4F0;
    --nextup:#F8B84E; --nextup-soft:#FFF3D8; --positive:#157A55; --pos-soft:#E4F1EA;
    --warning:#B85C00; --destructive:#C83D3D;
    --r-card:18px; --r-hero:22px; --r-sheet:28px; --r-input:14px;
    --shadow-soft:0 1px 3px rgba(39,35,33,.05),0 1px 2px rgba(39,35,33,.04);
    --shadow-card:0 6px 20px rgba(39,35,33,.08);
    --shadow-pill:0 6px 18px rgba(255,112,77,.35);
    --safe-top:env(safe-area-inset-top,0px); --safe-bottom:env(safe-area-inset-bottom,0px);
  }
  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
  html,body{margin:0;padding:0}
  body{
    font-family:'Heebo',system-ui,-apple-system,'Segoe UI',Arial,sans-serif;
    background:var(--bg); color:var(--ink); line-height:1.35;
    -webkit-font-smoothing:antialiased;
  }
  button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}
  input,textarea,select{font-family:inherit}
  #shell{max-width:480px;margin:0 auto;min-height:100dvh;background:var(--bg);position:relative;overflow-x:hidden}
  .tap{transition:transform .1s ease}
  .tap:active{transform:scale(.97)}
  .scroll{height:100dvh;overflow-y:auto;overflow-x:hidden}
  .carousel{display:flex;gap:12px;overflow-x:auto;padding:0 16px 4px;scrollbar-width:none}
  .carousel::-webkit-scrollbar{display:none}
  .noscroll{scrollbar-width:none}
  .noscroll::-webkit-scrollbar{display:none}

  /* Header */
  .hd{padding:calc(var(--safe-top) + 14px) 16px 4px}
  .hd h1{font-size:28px;font-weight:800;margin:2px 0 0;line-height:1.15}
  .hd .kick{font-size:14px;color:var(--muted);margin:0}
  .hd .sub{font-size:13.5px;color:var(--muted);margin:6px 0 0}
  .iconbtn{width:44px;height:44px;border-radius:999px;background:var(--surface);
    box-shadow:var(--shadow-soft);display:flex;align-items:center;justify-content:center;color:var(--ink)}
  .row-between{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}

  /* Search */
  .searchwrap{position:sticky;top:0;z-index:20;background:rgba(249,247,245,.95);
    backdrop-filter:blur(8px);padding:8px 16px;display:flex;gap:8px;align-items:center}
  .search{flex:1;height:52px;background:var(--surface);border-radius:16px;box-shadow:var(--shadow-soft);
    display:flex;align-items:center;padding:0 12px;gap:8px}
  .search input{flex:1;border:none;outline:none;background:transparent;font-size:16px;color:var(--ink)}
  .search input::placeholder{color:var(--muted)}
  .filterbtn{width:48px;height:48px;border-radius:16px;background:var(--surface);box-shadow:var(--shadow-soft);
    display:flex;align-items:center;justify-content:center;position:relative;color:var(--ink)}
  .badge-count{position:absolute;top:-4px;left:-4px;min-width:20px;height:20px;border-radius:999px;
    background:var(--primary);color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center;padding:0 5px}

  /* Categories */
  .cat{display:flex;flex-direction:column;align-items:center;gap:6px;width:70px;flex:0 0 auto}
  .cat .disc{width:54px;height:54px;border-radius:16px;background:var(--surface);box-shadow:var(--shadow-soft);
    display:flex;align-items:center;justify-content:center;font-size:26px;transition:.15s}
  .cat.active .disc{background:var(--primary-soft);box-shadow:inset 0 0 0 2px rgba(255,112,77,.4)}
  .cat .lbl{font-size:12px;color:var(--muted);font-weight:500}
  .cat.active .lbl{color:var(--primary);font-weight:700}
  .sec-title{font-size:19px;font-weight:800;padding:0 16px;margin:22px 0 10px;display:flex;justify-content:space-between;align-items:baseline}
  .sec-title .right{font-size:13px;color:var(--muted);font-weight:600}

  /* Chips */
  .chip{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:8px 14px;font-size:14px;font-weight:600;white-space:nowrap;border:1px solid transparent}
  .chip.off{background:var(--surface);color:var(--ink);border-color:var(--border)}
  .chip.on{background:var(--primary-soft);color:var(--primary)}
  .chiprow{display:flex;gap:8px;overflow-x:auto;padding:0 16px;scrollbar-width:none}
  .chiprow::-webkit-scrollbar{display:none}
  .badge{display:inline-flex;align-items:center;gap:5px;border-radius:999px;height:34px;padding:0 13px;font-size:13.5px;font-weight:600;background:#fff;border:1px solid #EDE8E4;color:#4E4945;white-space:nowrap}
  .b-neutral,.b-nextup,.b-primary,.b-pos{background:#fff;border:1px solid #EDE8E4;color:#4E4945}

  /* Cards */
  .card{position:relative;display:flex;gap:12px;background:var(--surface);border:1px solid var(--border);
    border-radius:var(--r-card);padding:12px;min-height:118px;overflow:hidden}
  .thumb{width:104px;height:104px;border-radius:var(--r-card);flex:0 0 auto;display:flex;align-items:center;justify-content:center;font-size:40px;overflow:hidden;background-size:cover;background-position:center}
  .card h3{font-size:18px;font-weight:800;margin:0;line-height:1.15;
    display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  .meta{font-size:13.5px;color:var(--muted);margin:2px 0 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .reason{font-size:12.5px;color:var(--primary);font-weight:600;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .star{position:absolute;top:8px;left:8px;width:38px;height:38px;border-radius:999px;
    display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.9);color:var(--muted);backdrop-filter:blur(4px);box-shadow:var(--shadow-soft)}
  .star.on{background:var(--nextup);color:#fff}
  .cardbody{min-width:0;flex:1;display:flex;flex-direction:column}
  .cardbadges{display:flex;gap:6px;flex-wrap:wrap;margin-top:auto;padding-top:8px}

  /* Carousel card */
  .ccard{width:172px;flex:0 0 auto;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-card);overflow:hidden}
  .ccard .cimg{height:122px;width:100%;display:flex;align-items:center;justify-content:center;font-size:46px;background-size:cover;background-position:center}
  .ccard .cbody{padding:10px}
  .ccard h3{font-size:15px;font-weight:800;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

  /* Hero */
  .hero{margin:0 16px;background:var(--surface);border-radius:var(--r-hero);box-shadow:var(--shadow-card);padding:12px;position:relative}
  .hero .himg{aspect-ratio:16/9;width:100%;border-radius:18px;display:flex;align-items:center;justify-content:center;font-size:64px;overflow:hidden;background-size:cover;background-position:center}
  .hero h3{font-size:21px;font-weight:800;margin:12px 4px 0}
  .heroact{display:flex;gap:8px;margin:12px 0 2px}

  /* Buttons */
  .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:999px;
    min-height:48px;padding:0 20px;font-size:15px;font-weight:700}
  .btn-primary{background:var(--primary);color:#fff;box-shadow:var(--shadow-pill)}
  .btn-primary:active{background:var(--primary-press)}
  .btn-soft{background:var(--primary-soft);color:var(--primary)}
  .btn-outline{background:var(--surface);color:var(--ink);border:1px solid var(--border)}
  .btn-danger{background:var(--destructive);color:#fff}
  .btn[disabled]{opacity:.45;box-shadow:none}
  .full{width:100%} .flex1{flex:1}

  /* Floating add */
  .fab{position:fixed;left:0;right:0;bottom:calc(var(--safe-bottom) + 16px);z-index:30;
    display:flex;justify-content:center;pointer-events:none;max-width:480px;margin:0 auto}
  .fab button{pointer-events:auto;height:54px;border-radius:999px;background:var(--primary);color:#fff;
    display:flex;align-items:center;gap:8px;padding:0 24px;font-size:16px;font-weight:700;box-shadow:var(--shadow-pill)}

  /* Empty */
  .empty{margin:32px 24px;text-align:center;color:var(--muted)}
  .empty .big{font-size:48px} .empty h3{color:var(--ink);font-size:18px;margin:12px 0 4px}

  /* Modal / sheet */
  #modal.show{position:fixed;inset:0;z-index:50}
  #modal .backdrop{position:absolute;inset:0;background:rgba(39,35,33,.35);animation:fade .18s ease}
  .sheet{position:absolute;left:0;right:0;bottom:0;max-width:480px;margin:0 auto;background:var(--surface);
    border-radius:var(--r-sheet) var(--r-sheet) 0 0;box-shadow:0 -10px 40px rgba(39,35,33,.18);
    max-height:92dvh;overflow-y:auto;overflow-x:hidden;animation:slideup .28s cubic-bezier(.22,1,.36,1)}
  .sheet.full{top:0;bottom:0;border-radius:0;max-height:none;height:100dvh}
  /* closing animations (mirror of the open ones) */
  #modal.closing .backdrop{animation:fade .2s ease forwards;opacity:0}
  #modal.closing .sheet{animation:slidedown .26s cubic-bezier(.4,0,.9,.4) forwards}
  .grip{width:44px;height:6px;border-radius:999px;background:var(--border);margin:12px auto 0}
  .sheet h2.title{font-size:19px;font-weight:800;padding:14px 20px 0}
  .sheethd{display:flex;align-items:center;justify-content:space-between;padding:calc(var(--safe-top) + 14px) 16px 12px;border-bottom:1px solid var(--border);position:sticky;top:0;background:var(--surface);z-index:2}
  .sheetfoot{position:sticky;bottom:0;background:rgba(255,255,255,.96);backdrop-filter:blur(8px);
    border-top:1px solid var(--border);padding:12px 16px calc(var(--safe-bottom) + 12px);display:flex;gap:8px}
  @keyframes fade{from{opacity:0}to{opacity:1}}
  @keyframes slideup{from{transform:translateY(100%)}to{transform:translateY(0)}}
  @keyframes slidedown{from{transform:translateY(0)}to{transform:translateY(100%)}}
  @media (prefers-reduced-motion: reduce){
    #modal.closing .backdrop,#modal.closing .sheet{animation:none}
  }

  /* Form */
  .field{display:block;margin-bottom:14px}
  .field>span{display:block;font-size:13px;font-weight:700;margin-bottom:6px}
  .inp{width:100%;background:var(--soft);border:1px solid transparent;border-radius:var(--r-input);
    padding:0 14px;min-height:52px;font-size:16px;color:var(--ink);outline:none}
  textarea.inp{min-height:84px;padding:12px 14px;line-height:1.5;resize:vertical}
  .inp:focus{border-color:rgba(255,112,77,.35);box-shadow:0 0 0 3px rgba(255,112,77,.15)}
  .seg{display:flex;gap:8px}
  .seg button{flex:1;border-radius:var(--r-input);padding:12px 0;font-size:14px;font-weight:700;background:var(--soft);color:var(--muted)}
  .seg button.on{background:var(--primary-soft);color:var(--primary)}
  .switch{display:flex;align-items:center;justify-content:space-between;background:var(--soft);border-radius:var(--r-input);padding:12px 16px}
  .switch input{width:24px;height:24px;accent-color:var(--primary)}
  .disclosure{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;padding:10px;color:var(--primary);font-weight:700;font-size:14px}
  .disclosure .disc-arrow{display:inline-block;transition:transform .3s cubic-bezier(.22,1,.36,1);font-size:15px;line-height:1}
  .disclosure.open .disc-arrow{transform:rotate(180deg)}
  /* animated open/close for "הוסף עוד פרטים" */
  .af-collapse{display:grid;grid-template-rows:0fr;transition:grid-template-rows .3s cubic-bezier(.22,1,.36,1)}
  .af-collapse.open{grid-template-rows:1fr}
  .af-collapse-inner{overflow:hidden;min-height:0;opacity:0;transform:translateY(8px);transition:opacity .28s ease-out,transform .28s ease-out}
  .af-collapse.open .af-collapse-inner{opacity:1;transform:none}
  @media (prefers-reduced-motion: reduce){
    .af-collapse{transition:none}
    .af-collapse-inner{transition:none}
    .disclosure .disc-arrow{transition:none}
  }
  /* decorative coral icon inside a link field — shared style for ALL icon fields.
     The .fic-wrap sits around only the input, so the icon centers on the input (not the label). */
  .fic-wrap{position:relative;display:block}
  .inp.has-fic{padding-inline-start:56px}          /* room so long URLs never touch the icon (RTL) */
  .fic{position:absolute;inset-inline-start:16px;top:50%;transform:translateY(-50%);
    width:24px;height:24px;display:flex;align-items:center;justify-content:center;pointer-events:none}
  .fic>.ui-ic{width:100%;height:100%;background-size:contain;background-position:center;background-repeat:no-repeat;opacity:.9}
  /* per-icon visual-weight tuning so every icon reads the same size on one baseline */
  .fic>.ic-phone{width:100%;height:100%}
  .fic>.ic-globe{width:91%;height:91%}
  .fic>.ic-book{width:96%;height:96%}
  .fic>.ic-clock{width:100%;height:100%}
  .fic>.ic-navpin{width:98%;height:98%}
  .fic>.ic-delivery{width:71%;height:71%}
  details.acc{background:var(--surface);border-radius:var(--r-card);box-shadow:var(--shadow-soft);margin-bottom:10px;overflow:hidden}
  details.acc>summary{list-style:none;padding:14px 16px;font-size:16px;font-weight:800;display:flex;align-items:center;gap:8px;cursor:pointer}
  details.acc>summary::-webkit-details-marker{display:none}
  details.acc .accbody{padding:0 16px 16px;font-size:15px;line-height:1.6}
  .daychip{width:34px;height:34px;border-radius:999px;font-size:13px;font-weight:800;background:var(--surface);color:var(--muted);border:1px solid var(--border)}
  .daychip.on{background:var(--primary);color:#fff;border-color:var(--primary)}
  .hhrow{background:var(--soft);border-radius:var(--r-input);padding:12px;margin-bottom:10px}
  .tag{display:inline-flex;align-items:center;gap:5px;border-radius:999px;background:var(--primary-soft);color:var(--primary);padding:5px 10px;font-size:13px;font-weight:700}

  /* Detail */
  .dhero{position:relative;height:42vh;display:flex;align-items:center;justify-content:center;font-size:92px;background-size:cover;background-position:center}
  .dtop{position:absolute;top:calc(var(--safe-top) + 10px);left:0;right:0;display:flex;justify-content:space-between;padding:0 16px}
  .dtop .iconbtn{background:rgba(255,255,255,.92);backdrop-filter:blur(6px)}
  .dactions{display:flex;gap:8px;margin-top:16px}
  .dact{flex:1;background:var(--surface);box-shadow:var(--shadow-soft);border-radius:var(--r-card);
    padding:12px 0;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:13px;font-weight:700}
  .dact .em{font-size:20px}
  .stickybar{position:fixed;left:0;right:0;bottom:0;max-width:480px;margin:0 auto;z-index:30;
    background:rgba(255,255,255,.96);backdrop-filter:blur(8px);border-top:1px solid var(--border);
    padding:12px 16px calc(var(--safe-bottom) + 12px);display:flex;gap:8px}

  /* Detail — redesigned */
  .nd-scroll{height:100dvh;overflow-y:auto;overflow-x:hidden;background:var(--bg)}
  .nd-hero{position:relative;height:36dvh;min-height:300px;max-height:340px;display:flex;align-items:center;justify-content:center}
  .nd-hero-img{font-size:120px;line-height:1;filter:drop-shadow(0 18px 22px rgba(39,35,33,.18));transform:translateY(-6px)}
  .nd-gal{position:absolute;inset:0;z-index:0;display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch}
  .nd-gal::-webkit-scrollbar{display:none}
  .nd-gal-slide{flex:0 0 100%;scroll-snap-align:center;background-position:center;background-repeat:no-repeat;background-size:cover}
  .nd-gal-multi{cursor:zoom-in}
  .nd-gal-count{position:absolute;bottom:14px;left:16px;z-index:3;display:inline-flex;align-items:center;gap:5px;background:rgba(255,255,255,.92);color:var(--ink);font-size:13px;font-weight:700;height:34px;padding:0 12px;border-radius:999px;box-shadow:0 2px 8px rgba(39,35,33,.12)}
  .nd-gal-dots{position:absolute;bottom:16px;left:0;right:0;z-index:3;display:flex;justify-content:center;gap:6px;pointer-events:none}
  .nd-gal-dots span{width:6px;height:6px;border-radius:999px;background:rgba(255,255,255,.75);box-shadow:0 1px 2px rgba(0,0,0,.18)}
  .nd-gal-dots span.on{width:8px;height:8px;background:var(--primary)}
  .nd-act-off{flex:1;display:flex;align-items:center;justify-content:center;gap:8px;background:#F7F5F3;border:1px solid #EFEAE6;border-radius:var(--r-card);padding:13px 6px;font-size:15px;font-weight:700;color:#B3ADA8;opacity:.75}
  .nd-act-off .ic{opacity:.55;filter:grayscale(.5)}
  #gfull{position:fixed;inset:0;z-index:80;background:rgba(20,18,17,.94);animation:fade .2s ease}
  #gfull .gf-track{position:absolute;inset:0;display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch}
  #gfull .gf-track::-webkit-scrollbar{display:none}
  #gfull .gf-slide{flex:0 0 100%;scroll-snap-align:center;background-position:center;background-repeat:no-repeat;background-size:contain}
  #gfull .gf-x{position:absolute;top:calc(var(--safe-top) + 14px);left:16px;z-index:2;width:44px;height:44px;border-radius:999px;background:rgba(255,255,255,.16);color:#fff;font-size:19px;display:flex;align-items:center;justify-content:center}
  #gfull .gf-count{position:absolute;top:calc(var(--safe-top) + 24px);right:20px;z-index:2;color:#fff;font-size:15px;font-weight:700}
  .nd-hero-top{position:absolute;top:calc(var(--safe-top) + 12px);left:0;right:0;display:flex;justify-content:space-between;padding:0 18px;z-index:3}
  .nd-hero-btn{width:52px;height:52px;border-radius:999px;background:#fff;display:flex;align-items:center;justify-content:center;
    font-size:22px;color:var(--ink);box-shadow:0 2px 10px rgba(39,35,33,.10)}
  .nd-sheet{position:relative;margin-top:-28px;background:#fff;border-radius:36px 36px 0 0;
    min-height:calc(65dvh + 28px);padding:0 20px 150px;box-shadow:none}
  .nd-grip{width:42px;height:5px;border-radius:999px;background:#E6E1DD;margin:0 auto;transform:translateY(16px)}
  .nd-titlerow{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding-top:38px}
  .nd-title h1{font-size:32px;font-weight:800;margin:0;line-height:1.06;letter-spacing:-.4px;text-align:right;color:#201F1D}
  .nd-title .nd-sub{font-size:17px;color:#938D88;margin:5px 0 0;font-weight:400}
  .nd-pill{flex:0 0 auto;display:inline-flex;align-items:center;gap:5px;background:#FFF4D8;color:#BB6300;
    font-weight:700;font-size:14px;height:36px;padding:0 14px;border-radius:999px;margin-top:6px;white-space:nowrap}
  .nd-meta{display:flex;align-items:center;justify-content:flex-start;flex-wrap:wrap;gap:0;margin-top:18px;color:#716C68;font-size:13.5px;font-weight:400}
  .nd-meta .mi{display:inline-flex;align-items:center;gap:5px;padding:0 14px;white-space:nowrap}
  .nd-meta .mi:first-child{padding-right:0}
  .nd-meta .sep{width:1px;height:20px;background:#E8E2DE}
  .nd-meta .mi .ui-ic{opacity:.9}
  .nd-meta .mi b{font-weight:650;color:#34312F}
  .nd-react{margin-top:12px}

  .nd-hh{display:flex;align-items:center;gap:12px;background:#FFF2EC;border:1px solid #F8D5C8;
    border-radius:22px;padding:14px 16px;margin-top:18px}
  .nd-hh-art{flex:0 0 auto;width:74px;height:84px;background-size:contain;background-position:center;background-repeat:no-repeat}
  .nd-hh-body{flex:1;min-width:0;text-align:right}
  .nd-hh-top{display:flex;align-items:center;gap:10px}
  .nd-hh-title{font-size:23px;font-weight:800;color:#FF694D}
  .nd-hh-day{background:rgba(255,255,255,.72);color:#847B75;border-radius:999px;height:32px;display:inline-flex;align-items:center;padding:0 12px;font-size:13px;font-weight:600}
  .nd-hh-sub{margin-top:7px;font-size:15px;color:#6F6965;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
  .nd-hh-pct{color:#FF6248;font-weight:750;font-size:20px}
  .nd-hh-sub .dot{color:#d7c8c0}

  .nd-actions{display:grid;grid-template-columns:repeat(var(--nd-cols,3),1fr);gap:10px;margin-top:14px}
  .nd-act{display:flex;align-items:center;justify-content:center;gap:8px;background:#fff;border:1px solid #EEE9E5;
    border-radius:18px;height:52px;font-size:15px;font-weight:650;color:#302D2A;box-shadow:0 3px 10px rgba(40,30,25,.045)}
  .nd-act .ic{display:inline-flex;align-items:center}
  .nd-act:active{background:#FFF7F3}
  .nd-act-off{display:flex;align-items:center;justify-content:center;gap:8px;background:#FAF8F6;border:1px solid #F0ECE8;border-radius:18px;height:52px;font-size:15px;font-weight:650;color:#BDB7B2;opacity:1;cursor:default}
  .nd-act-off .ic{opacity:.9;filter:grayscale(1) brightness(1.7) opacity(.7)}

  .nd-card{background:#fff;border:1px solid #EFEAE6;border-radius:20px;padding:16px;margin-top:14px;box-shadow:0 3px 12px rgba(46,35,30,.045)}
  .nd-card-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
  .nd-card-hd h3{font-size:18px;font-weight:750;margin:0;display:flex;align-items:center;gap:7px;color:#292624}
  .nd-dishrow{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding-bottom:2px}
  .nd-dishrow::-webkit-scrollbar{display:none}
  .nd-dish{flex:0 0 auto;display:inline-flex;align-items:center;gap:8px;background:#FAF8F6;border:1px solid #ECE7E3;
    border-radius:999px;height:40px;padding:0 6px 0 14px;font-size:13.5px;font-weight:500;color:#494541}
  .nd-dish .thumb2{width:32px;height:32px;border-radius:999px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:17px;border:1px solid #EEE9E5}
  .nd-more{flex:0 0 auto;width:36px;height:36px;border-radius:999px;background:#FFF7F3;color:#5A5551;
    display:flex;align-items:center;justify-content:center;font-size:16px;align-self:center}
  .nd-chips{display:flex;flex-wrap:wrap;gap:8px}
  .nd-chip{display:inline-flex;align-items:center;gap:5px;background:#fff;border:1px solid #EDE8E4;border-radius:999px;height:38px;padding:0 14px;font-size:14px;font-weight:600;color:#4E4945}
  .nd-details{padding:14px 16px 4px}
  .nd-detrow{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;text-align:right;min-height:42px;font-size:13.5px;color:#615C58;border:0;border-top:1px solid #F1EDEA;padding:0;background:none;text-decoration:none}
  a.nd-detrow,.nd-detrow *{text-decoration:none}
  .nd-details .nd-card-hd{margin-bottom:6px}
  .nd-details .nd-card-hd + .nd-detrow{border-top:none}
  .nd-detrow .dlabel{color:#615C58}
  .nd-detrow .dval{display:inline-flex;align-items:center;gap:7px;color:#615C58}
  .nd-detrow .em{color:var(--muted)}
  .nd-hours-list{display:flex;flex-direction:column;align-items:flex-end;gap:2px;line-height:1.5}
  .nd-detrow.nd-detrow-hours{align-items:flex-start;padding:11px 0}
  .nd-detrow.nd-detrow-hours .dval{align-items:flex-start}
  .nd-body-text{font-size:15px;line-height:1.6;color:#4a443f}
  .nd-visit{background:var(--soft);border-radius:14px;padding:10px 12px;margin-top:8px;font-size:14px}
  .nd-visit .vtop{display:flex;justify-content:space-between;font-weight:700}

  /* Filter sheet sections */
  .fbody{padding:12px 20px 6px}
  .fsec{margin-bottom:16px}
  .fsec>h3{font-size:14px;font-weight:800;margin:0 0 9px;color:var(--ink)}
  .fchips{display:flex;flex-wrap:wrap;gap:8px}
  .fchips .chip{height:38px;padding:0 14px;display:inline-flex;align-items:center;gap:5px;border-radius:999px;font-size:14px;font-weight:600;white-space:nowrap}
  .fchips .chip.off{background:#fff;border:1px solid #EDE8E4;color:#4E4945}
  .fchips .chip.on{background:#FFF0EA;border:1px solid #FF8A70;color:#E85F45}
  .fmore{height:38px;padding:0 14px;border-radius:999px;background:#FAF8F6;border:1px dashed #DED7D2;color:#8B857F;font-size:13.5px;font-weight:600;display:inline-flex;align-items:center}
  .ffclear{font-weight:700;color:var(--muted);padding:0 10px;background:none;border:none}
  @keyframes fchipIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

  /* Choose-for-me swipe cards */
  .cfm-stage{position:relative;min-height:252px}
  .cfm-card{position:absolute;left:0;right:0;top:0}
  .cfm-card .hero{margin:0;box-shadow:none;border:1px solid #EFEAE6;padding:10px}
  .cfm-card .himg{aspect-ratio:auto;height:150px}
  .cfm-card .hero h3{font-size:20px;margin:10px 4px 0}
  @keyframes cfmOut{from{transform:none;opacity:1}to{transform:translateX(-62%) rotate(-7deg);opacity:0}}
  @keyframes cfmIn{from{transform:translateX(60%) rotate(6deg);opacity:0}to{transform:none;opacity:1}}
  .cfm-card.cfm-out{animation:cfmOut .3s cubic-bezier(.4,0,.55,1) forwards;pointer-events:none}
  .cfm-card.cfm-in{animation:cfmIn .36s cubic-bezier(.22,1,.36,1) both}

  /* Menu popover */
  .pop{position:absolute;top:56px;left:16px;z-index:10;background:var(--surface);border-radius:16px;box-shadow:var(--shadow-card);overflow:hidden;width:190px;transform-origin:top left}
  @keyframes popIn{from{opacity:0;transform:translateY(-6px) scale(.94)}to{opacity:1;transform:none}}
  @keyframes popOut{from{opacity:1;transform:none}to{opacity:0;transform:translateY(-4px) scale(.96)}}
  @keyframes popRow{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
  .pop.pop-in{animation:popIn .24s cubic-bezier(.22,1,.36,1) both}
  .pop.pop-out{animation:popOut .17s ease-in both}
  .pop.pop-in button{animation:popRow .18s ease both}
  .pop.pop-in button:nth-child(1){animation-delay:55ms}
  .pop.pop-in button:nth-child(2){animation-delay:82ms}
  .pop.pop-in button:nth-child(3){animation-delay:109ms}
  .pop.pop-in button:nth-child(4){animation-delay:136ms}
  .pop button:active{background:var(--soft)}
  .pop button.danger:active{background:#FBECEC}
  @media (prefers-reduced-motion: reduce){ .pop.pop-in,.pop.pop-out,.pop.pop-in button{animation:none !important} }
  .pop button{display:block;width:100%;text-align:right;padding:13px 16px;font-size:14px;border-bottom:1px solid var(--border)}
  .pop button:last-child{border-bottom:none}

  /* Snackbar */
  #snack{position:fixed;left:0;right:0;bottom:calc(var(--safe-bottom) + 84px);max-width:480px;margin:0 auto;z-index:60;padding:0 16px;pointer-events:none}
  #snack .bar{pointer-events:auto;display:flex;align-items:center;justify-content:space-between;gap:12px;
    background:var(--ink);color:#fff;border-radius:16px;padding:13px 16px;box-shadow:var(--shadow-card);animation:slideup .2s ease}
  #snack .bar button{color:var(--nextup);font-weight:800;font-size:14px}

  /* Settings */
  .settsec{margin:0 16px 22px}
  .settsec h2{font-size:13px;font-weight:800;color:var(--muted);text-transform:uppercase;letter-spacing:.03em;margin:0 4px 8px}
  .settlist{background:var(--surface);border-radius:var(--r-card);box-shadow:var(--shadow-soft);overflow:hidden}
  .settrow{display:flex;align-items:center;gap:12px;width:100%;text-align:right;padding:15px 16px;border-bottom:1px solid var(--border)}
  .settrow:last-child{border-bottom:none}
  .settrow .em{font-size:18px}
  .settrow .t{flex:1}.settrow .t b{display:block;font-size:15px;font-weight:600}
  .settrow .t small{color:var(--muted);font-size:12.5px}
  .danger{color:var(--destructive)}
  a{color:var(--primary)}

  /* ===== Home — redesigned (aligned with detail page) ===== */
  .hd{padding:calc(var(--safe-top) + 16px) 18px 4px}
  .hd .kick{font-size:14px;color:#8a827c;font-weight:500}
  .hd h1{font-size:30px;font-weight:800;letter-spacing:-.5px;margin:2px 0 0}
  .hd .sub{font-size:14.5px;color:#8a827c;margin:6px 0 0}
  .hd .iconbtn{width:50px;height:50px;font-size:20px;box-shadow:0 2px 10px rgba(39,35,33,.08)}

  .searchwrap{position:sticky;top:0;z-index:20;background:rgba(250,248,246,.94);backdrop-filter:blur(10px);
    padding:10px 18px 10px;display:flex;gap:10px;align-items:center}
  .search{flex:1;height:58px;background:#fff;border:1px solid #f0ece7;border-radius:20px;
    box-shadow:0 3px 12px rgba(39,35,33,.05);display:flex;align-items:center;padding:0 16px;gap:10px;flex-direction:row}
  .search input{flex:1;border:none;outline:none;background:transparent;font-size:16px;color:var(--ink);text-align:right}
  .search input::placeholder{color:#a9a29c}
  .search .mag{order:3;display:flex;align-items:center}
  .search .clr{color:#a9a29c;font-size:15px;order:2}
  .filterbtn{width:56px;height:56px;border-radius:18px;background:#fff;border:1px solid #f0ece7;
    box-shadow:0 3px 12px rgba(39,35,33,.05);display:flex;align-items:center;justify-content:center;position:relative;color:var(--ink)}

  .sec-title{font-size:19px;font-weight:800;padding:0 18px;margin:26px 0 12px;display:flex;justify-content:space-between;align-items:baseline}
  .sec-title .right{font-size:14px;color:#8a827c;font-weight:600}

  .cat{width:66px}
  .cat .disc{width:58px;height:58px;border-radius:18px;background:#fff;border:1px solid #f2eee9;
    box-shadow:0 2px 8px rgba(39,35,33,.05);font-size:27px}
  .cat.active .disc{background:var(--primary-soft);border-color:transparent;box-shadow:inset 0 0 0 2px rgba(255,112,77,.35)}
  .cat .lbl{font-size:12.5px;color:#6f6862;font-weight:600}
  .cat.active .lbl{color:var(--primary);font-weight:700}
  .carousel{padding:0 18px 4px}
  .catwrap{position:relative}
  .catwrap .cat-fade{position:absolute;top:0;bottom:6px;left:0;width:30px;background:linear-gradient(to left,rgba(250,248,246,0),var(--bg) 78%);pointer-events:none;z-index:2}
  .cat-end{flex:0 0 6px}

  /* Featured card */
  .fh{margin:0 18px;background:#fff;border-radius:26px;box-shadow:0 8px 26px rgba(39,35,33,.08);overflow:hidden}
  .fh-img{position:relative;aspect-ratio:16/10;width:100%;display:flex;align-items:center;justify-content:center;font-size:96px}
  .fh-img .em{filter:drop-shadow(0 12px 16px rgba(39,35,33,.16))}
  .fh-menu{position:absolute;top:12px;left:12px;width:40px;height:40px;border-radius:999px;background:#fff;z-index:2;
    display:flex;align-items:center;justify-content:center;font-size:18px;color:var(--ink);box-shadow:0 2px 8px rgba(39,35,33,.12)}
  .fh-badge{position:absolute;top:14px;right:14px;background:var(--nextup-soft);color:var(--warning);z-index:2;
    font-weight:800;font-size:13.5px;padding:7px 13px;border-radius:999px}
  .fh-body{padding:16px 18px 18px}
  .fh-info h3{font-size:24px;font-weight:800;margin:0;letter-spacing:-.3px}
  .fh-sub{font-size:15px;color:#8a827c;margin:3px 0 0}
  .fh-status{font-size:14.5px;color:var(--primary);font-weight:700;margin:6px 0 0}
  .fh-actions{display:flex;gap:10px;margin-top:14px}
  .fh-actions .p{flex:7;background:var(--primary);color:#fff;box-shadow:var(--shadow-pill)}
  .fh-actions .p:active{background:var(--primary-press)}
  .fh-actions .s{flex:3;background:var(--primary-tint);color:var(--primary)}
  .fh-actions .btn{min-height:52px;font-size:15.5px}

  /* Featured empty prompt */
  .fh-empty{margin:0 18px;background:var(--cream);border-radius:26px;padding:20px;box-shadow:var(--shadow-soft)}
  .fh-empty h3{margin:0 0 4px;font-size:18px}

  /* "מתאים עכשיו" small tinted cards */
  .mc{width:124px;flex:0 0 auto;border-radius:20px;padding:12px;border:1px solid rgba(39,35,33,.04);
    display:flex;flex-direction:column;gap:2px;min-height:150px}
  .mc-img{width:46px;height:46px;border-radius:14px;background:rgba(255,255,255,.6);display:flex;align-items:center;justify-content:center;font-size:26px;margin-bottom:6px}
  .mc-head{font-size:15px;font-weight:800;color:var(--ink);line-height:1.15}
  .mc-sub{font-size:12.5px;color:#8a827c;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .mc-status{margin-top:auto;font-size:12px;font-weight:700;color:#6f6862}

  /* All-places compact card */
  .card{min-height:108px;border-radius:22px;border:1px solid #f1ede8;box-shadow:0 2px 10px rgba(39,35,33,.045);
    padding:12px;gap:14px;align-items:center}
  .card h3{font-size:18px}
  .card .meta{font-size:13.5px}
  .thumb{width:92px;height:92px;border-radius:20px;font-size:38px}
  .cardbadges{padding-top:6px}

  /* Sticky add CTA */
  .fab{position:fixed;left:0;right:0;bottom:0;max-width:480px;margin:0 auto;z-index:30;display:block;
    padding:12px 18px calc(var(--safe-bottom) + 14px);
    background:linear-gradient(to top,var(--bg) 62%,rgba(250,248,246,0));pointer-events:none}
  .fab button{pointer-events:auto;width:100%;height:58px;border-radius:999px;background:var(--primary);color:#fff;
    font-size:16.5px;font-weight:800;display:flex;align-items:center;justify-content:center;gap:8px;box-shadow:var(--shadow-pill)}
  .fab button:active{background:var(--primary-press)}

  /* Compact featured recommendation card */
  .fhc{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;-webkit-overflow-scrolling:touch;scrollbar-width:none}
  .fhc::-webkit-scrollbar{display:none}
  .fhc-slide{flex:0 0 100%;scroll-snap-align:center}
  .fhc-dots{display:flex;justify-content:center;gap:6px;margin-top:11px}
  .fhc-dot{width:7px;height:7px;border-radius:999px;background:#D9D4D0;border:none;padding:0;transition:width .2s,background .2s}
  .fhc-dot.on{width:18px;background:var(--primary)}
  /* Featured two-panel card (image left · white content right · seam gradient) */
  .fc{position:relative;margin:0 18px;height:184px;border-radius:26px;overflow:hidden;background:#fff;box-shadow:0 6px 22px rgba(39,35,33,.08)}
  .fc-img{position:absolute;top:0;bottom:0;left:0;width:62%;z-index:0;background-position:center;background-repeat:no-repeat;background-size:cover}
  .fc-imgemoji{display:flex;align-items:center;justify-content:center;font-size:72px;background:var(--blush)}
  .fc-seam{position:absolute;top:0;bottom:0;right:45%;width:72px;z-index:1;background:linear-gradient(to right,rgba(255,255,255,0),#fff)}
  .fc-panel{position:absolute;top:0;bottom:0;right:0;width:45%;z-index:2;background:#fff;padding:13px 15px 70px;text-align:right;display:flex;flex-direction:column;overflow:hidden}
  .fc-badge{align-self:flex-start;display:inline-flex;align-items:center;gap:4px;background:var(--nextup-soft);color:var(--warning);font-weight:800;font-size:12px;padding:5px 10px;border-radius:999px}
  .fc-panel h3{font-size:21px;font-weight:800;margin:7px 0 0;line-height:1.15;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .fc-panel .sub{font-size:13px;color:#8a827c;margin:3px 0 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .fc-panel .st{font-size:12.5px;font-weight:700;color:var(--primary);margin:6px 0 0;line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .fc-hh30{color:var(--primary-press);font-weight:800;font-size:14px}
  .fc-menu{position:absolute;top:12px;left:12px;z-index:3;width:38px;height:38px;border-radius:999px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:17px;color:var(--ink);box-shadow:0 2px 8px rgba(39,35,33,.14)}
  .fc-actions{position:absolute;left:12px;right:12px;bottom:14px;z-index:3;display:flex;gap:9px}
  .fc-actions .p{flex:1 1 0;min-width:0;height:46px;border-radius:999px;background:var(--primary);color:#fff;font-weight:700;font-size:14.5px;display:flex;align-items:center;justify-content:center;box-shadow:var(--shadow-pill)}
  .fc-actions .p:active{background:var(--primary-press)}
  .fc-actions .s{flex:1 1 0;min-width:0;height:46px;border-radius:999px;background:#fff;color:var(--primary);font-weight:700;font-size:14px;display:flex;align-items:center;justify-content:center;gap:5px;box-shadow:0 2px 9px rgba(39,35,33,.14)}
  .hh30{color:var(--primary-press);font-weight:800;font-size:18px}
  .fh2{position:relative;margin:0 18px;height:172px;border-radius:24px;overflow:hidden;background:#fff;box-shadow:0 6px 22px rgba(39,35,33,.08)}
  .fh2 .imgfill{z-index:0}
  .fh2-emoji{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:80px;z-index:0}
  .fh2-grad{position:absolute;inset:0;z-index:1;background:linear-gradient(to left,#fff 0%,rgba(255,250,248,.97) 30%,rgba(255,250,248,.62) 50%,rgba(255,250,248,0) 74%)}
  .fh2-menu{position:absolute;top:12px;left:12px;z-index:3;width:40px;height:40px;border-radius:999px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:18px;color:var(--ink);box-shadow:0 2px 8px rgba(39,35,33,.14)}
  .fh2-badge{position:absolute;top:14px;right:16px;z-index:3;display:inline-flex;align-items:center;gap:4px;background:var(--nextup-soft);color:var(--warning);font-weight:800;font-size:12.5px;padding:6px 11px;border-radius:999px}
  .fh2-body{position:absolute;inset:0;z-index:2;display:flex;flex-direction:column;justify-content:space-between;padding:14px 16px;pointer-events:none}
  .fh2-body button{pointer-events:auto}
  .fh2-info{text-align:right;margin-top:32px}
  .fh2-info h3{font-size:23px;font-weight:800;margin:0;line-height:1.05;color:var(--ink)}
  .fh2-info .sub{font-size:14px;color:#8a827c;margin:3px 0 0}
  .fh2-info .st{font-size:13.5px;font-weight:700;color:var(--primary);margin:5px 0 0}
  .fh2-actions{display:flex;gap:8px}
  .fh2-actions .p{flex:2.3;height:46px;border-radius:999px;background:var(--primary);color:#fff;font-size:15px;font-weight:700;display:flex;align-items:center;justify-content:center;box-shadow:var(--shadow-pill)}
  .fh2-actions .p:active{background:var(--primary-press)}
  .fh2-actions .s{flex:1;height:46px;border-radius:999px;background:var(--primary-tint);color:var(--primary);font-size:14px;font-weight:700;display:flex;align-items:center;justify-content:center;gap:5px}
  /* Matches-now compact card (tag-first) */
  .mc2{position:relative;width:126px;height:140px;flex:0 0 auto;border-radius:20px;padding:12px;overflow:hidden;border:1px solid rgba(0,0,0,.045);display:flex;flex-direction:column}
  .mc2-tag{font-size:14px;font-weight:800;color:var(--ink);line-height:1.15}
  .mc2-name{font-size:13.5px;font-weight:700;color:#5a534e;margin-top:5px}
  .mc2-ic{position:absolute;bottom:8px;left:6px;width:52px;height:52px;background-size:contain;background-position:center;background-repeat:no-repeat}
  .mc2-emoji{position:absolute;bottom:8px;left:10px;font-size:38px}
  .mc2-status{margin-top:auto;font-size:10px;font-weight:600;text-align:right;opacity:.9}

  /* Entrance animations */
  @keyframes nbEnter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
  @keyframes nbEnterS{from{opacity:0;transform:translateY(12px) scale(.985)}to{opacity:1;transform:none}}
  @keyframes nbEnterX{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:none}}
  .nb-rev{opacity:0;transform:translateY(14px)}
  .nb-rev.nb-in{opacity:1;transform:none;transition:opacity .42s cubic-bezier(.22,1,.36,1),transform .42s cubic-bezier(.22,1,.36,1)}
  @media (prefers-reduced-motion: reduce){
    .nb-rev,.nb-rev.nb-in{opacity:1 !important;transform:none !important;transition:none !important}
  }

  /* Embedded food images */
  .bgimg{background-size:cover;background-position:center;background-repeat:no-repeat}
  .nd-hh-art.bgimg{background-size:contain;background-color:transparent}
  .imgfill{position:absolute;inset:0;background-position:center;background-repeat:no-repeat;background-size:contain;pointer-events:none;z-index:0}
  .imgfill.cover{background-size:cover}
  .thumb,.mc-img,.cat .disc,.fh-img,.nd-hero,.himg{position:relative;overflow:hidden}
  /* small icon contexts get a touch of breathing room */
  .thumb .imgfill:not(.cover),.mc-img .imgfill:not(.cover),.cat .disc .imgfill:not(.cover){inset:9%}
  /* inline UI icons (settings, filter, location, star) */
  .ui-ic{display:inline-block;background-size:contain;background-position:center;background-repeat:no-repeat;vertical-align:-0.18em;flex:0 0 auto}

  /* ===== Add-place sheet ===== */
  .af-head{background:linear-gradient(180deg,#FCE4DA 0%,#FBEDE6 62%,var(--surface) 100%);padding:calc(var(--safe-top) + 18px) 20px 0}
  .af-head .row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
  .af-title{font-size:25px;font-weight:800;color:var(--ink);margin:0}
  .af-sub{font-size:14px;color:#8B8580;margin:5px 0 0}
  .af-x{width:48px;height:48px;border-radius:999px;background:#fff;box-shadow:0 2px 10px rgba(39,35,33,.10);display:flex;align-items:center;justify-content:center;font-size:19px;color:var(--ink);flex:0 0 auto}
  .af-ai{display:flex;align-items:center;gap:12px;width:100%;text-align:right;background:#fff;border-radius:20px;box-shadow:0 4px 16px rgba(39,35,33,.07);padding:13px 14px;margin:16px 0 18px}
  .af-ai .rb{width:46px;height:46px;border-radius:999px;background:var(--primary-tint);display:flex;align-items:center;justify-content:center;flex:0 0 auto}
  .af-ai .txt{flex:1;min-width:0}
  .af-ai .txt b{display:block;font-size:14.5px;font-weight:800;color:var(--primary);line-height:1.35}
  .af-ai .txt small{font-size:12.5px;color:#8B8580}
  .af-ai .chev{color:#B7B0AA;font-size:20px;flex:0 0 auto}
  .af-body{padding:2px 20px 26px;background:var(--surface);overflow-x:hidden}
  .af-field{margin-bottom:18px;min-width:0}
  .af-field>span{display:block;font-size:15px;font-weight:700;margin-bottom:8px;color:var(--ink)}
  .af-inp{display:flex;align-items:center;background:#fff;border:1px solid #ECE8E4;border-radius:16px;overflow:hidden;min-width:0}
  .af-inp input{flex:1;min-width:0;width:100%;border:none;outline:none;background:transparent;height:56px;padding:0 14px;font-size:16px;color:var(--ink)}
  .af-inp input::placeholder{color:#A39D98}
  .af-inp .ib{width:52px;height:56px;display:flex;align-items:center;justify-content:center;border-right:1px solid #F1EDE9;flex:0 0 auto}
  .af-inp:focus-within{border-color:#FF9A84;box-shadow:0 0 0 3px rgba(255,112,77,.12)}
  .af-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
  .af-grid>*{min-width:0}
  .af-price{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
  .af-price button{background:#fff;border:1px solid #ECE8E4;border-radius:16px;height:80px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:#8B8580;font-weight:700}
  .af-price button .p{font-size:13.5px;letter-spacing:-1px}
  .af-price button .ui-ic{width:26px;height:22px}
  .af-price button.on{background:#FFF2EC;border:1.5px solid #FF8A70;color:var(--primary)}
  .af-status{display:grid;grid-template-columns:1fr 1fr;gap:12px}
  .af-status button{height:64px;border-radius:16px;background:#fff;border:1px solid #ECE8E4;color:#8B8580;font-size:16px;font-weight:700;display:flex;align-items:center;justify-content:center;gap:8px}
  .af-status button .ui-ic{width:30px;height:30px}
  .af-status button[data-s="0"].on{background:#FFF2EC;border-color:#FF9A84;color:var(--primary)}
  .af-status button[data-s="1"].on{background:#EEF8F2;border-color:#9AD8B8;color:var(--positive)}
  .af-next{display:flex;align-items:center;gap:12px;background:#fff;border:1px solid #ECE8E4;border-radius:16px;padding:14px 16px;margin-bottom:16px;cursor:pointer}
  .af-next .sbox{width:44px;height:44px;border-radius:12px;background:#FFF5D9;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
  .af-next .sbox .ui-ic{width:24px;height:24px}
  .af-next .txt{flex:1;min-width:0}
  .af-next .txt b{display:block;font-size:16px;font-weight:700;color:var(--ink)}
  .af-next .txt small{font-size:12.5px;color:#8B8580}
  .af-check{position:absolute;opacity:0;width:0;height:0}
  .af-toggle{width:48px;height:28px;border-radius:999px;background:#D9D3CD;position:relative;flex:0 0 auto;transition:background .15s}
  .af-toggle::after{content:"";position:absolute;top:3px;right:3px;width:22px;height:22px;border-radius:999px;background:#fff;transition:.15s;box-shadow:0 1px 3px rgba(0,0,0,.15)}
  .af-check:checked ~ .af-toggle{background:var(--primary)}
  .af-check:checked ~ .af-toggle::after{right:auto;left:3px}
  /* מתאים ל tags */
  .af-help{font-size:12.5px;color:#8B8580;margin:-2px 0 10px}
  .af-tags{display:flex;flex-wrap:wrap;gap:8px}
  .af-tag{display:inline-flex;align-items:center;gap:5px;height:38px;padding:0 14px;border-radius:999px;background:#fff;border:1px solid #ECE8E4;color:#595451;font-size:14px;font-weight:600;cursor:pointer}
  .af-tag.on{background:#FFF0EA;border-color:#FF8A70;color:#E95F45}
  .af-tag .ck{font-size:11px;font-weight:800}
  /* cuisine selector field */
  .af-select{width:100%;cursor:pointer;padding:0;text-align:right}
  .af-selval{flex:1;min-width:0;display:flex;align-items:center;gap:6px;padding:0 14px;height:56px;overflow:hidden}
  .af-selval .ph{color:#A39D98;font-size:16px}
  .af-selnames{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:15.5px;font-weight:600;color:var(--ink)}
  .af-selchip{display:inline-flex;align-items:center;gap:4px;background:var(--soft);border-radius:999px;padding:4px 10px;font-size:14px;font-weight:600;white-space:nowrap}
  .af-chev{color:#B7B0AA;font-size:20px;display:flex;align-items:center;padding:0 6px;flex:0 0 auto}
  /* ===== Dish theme image picker ===== */
  .af-theme{margin-bottom:18px}
  .af-theme-row{display:flex;align-items:center;gap:12px}
  .af-theme-preview{position:relative;width:84px;height:84px;border-radius:18px;overflow:hidden;flex:0 0 auto;border:1.5px solid #ECE8E4;background:var(--blush);cursor:pointer;box-shadow:0 3px 12px rgba(39,35,33,.08);transition:transform .12s ease,border-color .15s ease}
  .af-theme-preview:active{transform:scale(.96)}
  .af-theme-preview.open{border-color:#FF8A70;box-shadow:0 4px 16px rgba(255,112,77,.24)}
  .af-theme-preview .imgfill{inset:0}
  .af-theme-preview .af-theme-edit{position:absolute;bottom:5px;left:5px;width:26px;height:26px;border-radius:999px;background:rgba(39,35,33,.55);backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;z-index:2}
  .af-theme-preview .af-theme-emoji{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:38px}
  .af-theme-meta{flex:1;min-width:0}
  .af-theme-meta b{display:block;font-size:15px;font-weight:700;color:var(--ink)}
  .af-theme-meta small{display:block;font-size:12.5px;color:#8B8580;margin-top:2px;line-height:1.4}
  .af-theme-meta .cur{display:inline-flex;align-items:center;gap:5px;margin-top:6px;font-size:13px;font-weight:700;color:var(--primary)}
  /* animated expandable strip */
  .af-theme-grid{display:grid;grid-template-rows:0fr;transition:grid-template-rows .34s cubic-bezier(.22,1,.36,1);margin-top:0}
  .af-theme-grid.open{grid-template-rows:1fr;margin-top:14px}
  .af-theme-grid-inner{overflow:hidden;min-height:0}
  .af-theme-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:2px}
  .af-theme-item{position:relative;border-radius:16px;overflow:hidden;aspect-ratio:1/1;border:1.5px solid #ECE8E4;background:var(--blush);cursor:pointer;opacity:0;transform:translateY(8px) scale(.96)}
  .af-theme-grid.open .af-theme-item{animation:themePop .32s cubic-bezier(.22,1,.36,1) forwards}
  .af-theme-item .imgfill{inset:0}
  .af-theme-item .lbl{position:absolute;left:0;right:0;bottom:0;padding:14px 6px 5px;font-size:11px;font-weight:700;color:#fff;text-align:center;background:linear-gradient(180deg,rgba(39,35,33,0) 0%,rgba(39,35,33,.62) 100%);z-index:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .af-theme-item.on{border-color:#FF7A5C;box-shadow:0 0 0 3px rgba(255,112,77,.20)}
  .af-theme-item .tick{position:absolute;top:5px;left:5px;width:22px;height:22px;border-radius:999px;background:var(--primary);color:#fff;display:none;align-items:center;justify-content:center;font-size:12px;font-weight:800;z-index:2;box-shadow:0 2px 6px rgba(0,0,0,.2)}
  .af-theme-item.on .tick{display:flex}
  .af-theme-auto{grid-column:1 / -1;display:flex;align-items:center;justify-content:center;gap:6px;height:40px;border-radius:14px;border:1px dashed #D9D3CD;background:#fff;color:#8B8580;font-size:13.5px;font-weight:700;cursor:pointer}
  .af-theme-auto.on{border:1.5px solid #FF8A70;background:#FFF2EC;color:var(--primary)}
  @keyframes themePop{to{opacity:1;transform:none}}
  @media (prefers-reduced-motion: reduce){
    .af-theme-grid{transition:none}
    .af-theme-grid.open .af-theme-item{animation:none;opacity:1;transform:none}
  }
  /* cuisine picker overlay */
  #cpick{position:fixed;inset:0;z-index:70}
  #cpick .bd{position:absolute;inset:0;background:rgba(39,35,33,.35);animation:fade .18s ease}
  #cpick .sh{position:absolute;left:0;right:0;bottom:0;max-width:480px;margin:0 auto;background:#fff;border-radius:28px 28px 0 0;max-height:82dvh;display:flex;flex-direction:column;box-shadow:0 -10px 40px rgba(39,35,33,.18);animation:slideup .28s cubic-bezier(.22,1,.36,1)}
  #cpick .hd{padding:18px 20px 10px;text-align:right}
  #cpick .hd h3{margin:0 0 10px;font-size:19px;font-weight:800}
  #cpick .search{display:flex;align-items:center;gap:8px;background:var(--soft);border-radius:14px;padding:0 12px}
  #cpick .search input{flex:1;min-width:0;border:none;outline:none;background:transparent;height:46px;font-size:15px;text-align:right}
  #cpick .list{overflow-y:auto;padding:6px 12px}
  #cpick .row{display:flex;align-items:center;gap:12px;width:100%;padding:11px 12px;border-radius:14px;text-align:right;font-size:15px;font-weight:600;color:var(--ink)}
  #cpick .row .nm{flex:1}
  #cpick .row .chk{width:22px;height:22px;border-radius:999px;border:2px solid #DDD7D1;display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;flex:0 0 auto}
  #cpick .row.on .chk{background:var(--primary);border-color:var(--primary)}
  #cpick .foot{padding:12px 16px calc(var(--safe-bottom) + 12px);border-top:1px solid var(--border)}
